Rules.InvariantScript:
Set(
    varItem,
    LookUp(
        'items (v2.0)',
        number = First(Self.Barcodes).Value
    )
);
Set(
    varOpeningBalance,
    LookUp(
        'itemLedgerEntries (microsoft/analytics/v1.0)',
        'Item No.' = First(Self.Barcodes).Value
    ).Quantity
);
Set(varJustSelected, true);
Set(varBarcodeText, First(Self.Barcodes).Value);
Reset(txtSearch)

Set(varJustSelected, true);
Set(varItem, ThisItem);
Set(varBarcodeText, ThisItem.number);

Set(
    varOpeningBalance,
    LookUp(
        'itemLedgerEntries (microsoft/analytics/v1.0)',
        'Item No.' = ThisItem.number
    ).Quantity
);

Set(varNewPicture, Blank());

IfError(
    Set(
        varItemPicture,
        'PowerAppV2->Compose,Findonerecord(V3),Getanimage,fileordo...'.Run(
            ThisItem.number
        ).picture
    ),
    Set(varItemPicture, Blank())
)

If(
    varJustSelected,
    false,
    
    With(
        {
            found:
                LookUp(
                    'items (v2.0)',
                    number = txtSearch.Text
                )
        },
        If(
            IsBlank(Trim(txtSearch.Text)) || IsBlank(found),

            Set(varItem, Blank());
            Set(varOpeningBalance, Blank()),

            Set(varItem, found);
            Set(
                varOpeningBalance,
                LookUp(
                    'itemLedgerEntries (microsoft/analytics/v1.0)',
                    'Item No.' = found.number
                ).Quantity
            )
        )
    )
)

ControlPropertyState.AutoRuleBindingString:
Patch(
    InventoryCount,
    Defaults(InventoryCount),
    {
        Title: varItem.number,
        ItemNo: varItem.number,
        ItemName: varItem.'Display Name',
        LocationCode:
            LookUp(
                'itemLedgerEntries (microsoft/analytics/v1.0)',
                'Item No.' = varItem.number
            ).'Location Code',
        OpeningBalance: Value(Label8_5.Text),
        CountQty: Value(txtCountQty.Text),
        Variance:
            Value(Label8_5.Text) -
            Value(txtCountQty.Text),
        CountDate: Now(),
        Counter: User().FullName
    }
);

Notify("Амжилттай хадгалагдлаа", NotificationType.Success);

Set(varItem, Blank());
Set(varOpeningBalance, Blank());
Set(varBarcodeText, Blank());
Reset(txtCountQty);
Reset(txtSearch)

Rules.InvariantScript:
Set(
    varUploadPicture,
    Substitute(
        JSON(
            Image8.Image,
            JSONFormat.IncludeBinaryData
        ),
        """",
        ""
    )
);

If(
    StartsWith(varUploadPicture, "data:image"),
    
    IfError(
        'PowerAppV2->Getrecord(V3)'.Run(
            varItem.number,
            varUploadPicture
        ),
        
        Notify(
            "Зураг хадгалахад алдаа гарлаа",
            NotificationType.Error
        ),
        
        Notify(
            "Зураг BC-д амжилттай хадгалагдлаа",
            NotificationType.Success
        )
    ),
    
    Notify(
        "Зураг Base64 формат руу хөрвөөгүй байна",
        NotificationType.Error
    )
)

If(
    IsBlank(Trim(txtSearch.Text)) ||
    IsBlank(varItem) ||
    CountRows(
        Filter(
            InventoryCount,
            ItemNo = varItem.number
        )
    ) = 0,
    "-",
    With(
        {
            openingQty:
                LookUp(
                    'itemLedgerEntries (microsoft/analytics/v1.0)',
                    'Item No.' = varItem.number
                ).Quantity,

            countedQty:
                Sum(
                    Filter(
                        InventoryCount,
                        ItemNo = varItem.number
                    ),
                    CountQty
                )
        },
        With(
            {
                diff: countedQty - openingQty
            },
            If(
                diff > 0,
                "+" & Text(diff, "#,##0"),
                Text(diff, "#,##0")
            )
        )
    )
)

If(
    IsBlank(varItem),
    RGBA(100,100,100,1),
    With(
        {
            openingQty:
                LookUp(
                    'itemLedgerEntries (microsoft/analytics/v1.0)',
                    'Item No.' = varItem.number
                ).Quantity,
            countedQty:
                Sum(
                    Filter(
                        InventoryCount,
                        ItemNo = varItem.number
                    ),
                    CountQty
                )
        },
        With(
            {
                diff: countedQty - openingQty
            },
            If(
                diff = 0,
                RGBA(22,163,74,1),
                diff > 0,
                RGBA(217,119,6,1),
                RGBA(220,38,38,1)
            )
        )
    )
)

If(
    IsBlank(varItem),
    RGBA(245,245,245,1),
    With(
        {
            openingQty:
                LookUp(
                    'itemLedgerEntries (microsoft/analytics/v1.0)',
                    'Item No.' = varItem.number
                ).Quantity,
            countedQty:
                Sum(
                    Filter(
                        InventoryCount,
                        ItemNo = varItem.number
                    ),
                    CountQty
                )
        },
        With(
            {
                diff: countedQty - openingQty
            },
            If(
                diff = 0,
                RGBA(220,252,231,1),
                diff > 0,
                RGBA(255,243,205,1),
                RGBA(254,226,226,1)
            )
        )
    )
)
